function toolPage(tool) {
  const file = `ias/${tool.slug}.html`;
  const canonical = `${base}/${file}`;
  const title = `${tool.name}: guía práctica y límites`;
  const description = `Guía editorial de ${tool.name}: para qué sirve, prueba práctica, prompt reproducible, verificación y límites.`;
  return `${head({prefix:"../",title:`${title} | IA FUTURE`,description,canonical,schema:[articleSchema({title,description,canonical})]})}${header("../","catalogo")}<main id="top"><section class="tool-hero" style="--accent:#00e0ff"><div class="tool-hero-copy reveal">${breadcrumbs("../",[["Inicio","index.html"],["Herramientas","catalogo.html"],[tool.name,""]])}<span class="eyebrow"><span></span>${tool.maker}</span><h1>${tool.name}</h1><p>${tool.description}</p>${editorialMeta("../")}</div><div class="tool-hero-visual reveal"><span class="ai-logo big" style="--accent:#00e0ff"><b>${tool.name.slice(0,2).toUpperCase()}</b></span><div class="orbit"></div></div></section><section class="section compact"><article class="article-prose"><section><h2>Cuándo aporta valor</h2><p>${tool.best}</p><p>IA FUTURE no puntúa la herramienta por cantidad de funciones. La evaluamos por la claridad del resultado, el control que conserva el usuario y la facilidad para verificar lo producido.</p></section><section><h2>Cuándo no conviene usarla</h2><p>${tool.avoid}</p><p>Si la tarea afecta una calificación, una decisión importante o datos de terceros, conserva el material original y documenta las comprobaciones.</p></section><section><h2>Prueba práctica de 30 minutos</h2><p>${tool.exercise}</p><ol><li>Define qué resultado sería correcto.</li><li>Usa material que tengas permiso de compartir.</li><li>Guarda la primera respuesta.</li><li>Introduce una corrección y observa cómo reacciona.</li><li>Comprueba el resultado fuera de la herramienta.</li></ol></section><section><h2>Prompt de laboratorio</h2><div class="prompt-sample">${tool.prompt}</div><p>Modifica el contexto y el criterio de verificación. No agregues detalles que no puedas comprobar.</p></section><section><h2>Checklist de verificación</h2><ul><li>La respuesta distingue hechos de recomendaciones.</li><li>Las fuentes existen y respaldan la afirmación.</li><li>No se compartieron datos personales.</li><li>El resultado responde a la consigna real.</li><li>Puedes explicar y editar la versión final.</li></ul></section>${sources([[`Documentación oficial de ${tool.name}`,tool.official],["Metodología editorial de IA FUTURE",`${base}/metodologia.html`]])}</article></section></main>${footer("../")}`;
}

function homepage() {
  const canonical = `${base}/`;
  const description = "Guías prácticas y comparativas de inteligencia artificial para estudiar, investigar y crear con verificación humana.";
  const schema = [{"@context":"https://schema.org","@type":"WebSite",name:"IA FUTURE",url:canonical,description},{"@context":"https://schema.org","@type":"Organization",name:"IA FUTURE",url:canonical}];
  return `${head({title:"IA FUTURE | Guías prácticas de inteligencia artificial",description,canonical,type:"website",schema})}${header("","inicio")}<main id="top"><section class="home-hero"><div class="hero-copy reveal"><span class="eyebrow"><span></span> Aprender, comprobar y decidir</span><h1><span>IA</span><span>FUTURE</span></h1><p class="hero-lead">Guías independientes para usar inteligencia artificial en estudio, investigación y creación sin delegar el criterio, las fuentes ni la autoría.</p><div class="hero-actions"><a class="button primary" href="noticias.html">Abrir guías</a><a class="button ghost" href="metodologia.html">Ver metodología</a></div><div class="hero-metrics"><span><strong>4</strong>guías de método</span><span><strong>4</strong>comparativas</span><span><strong>5</strong>fichas verificables</span><span><strong>Humano</strong>revisión editorial</span></div></div><div class="premium-hero-image reveal" data-tilt><img src="assets/img/hero-robot-premium.webp" alt="Laboratorio visual de inteligencia artificial de IA FUTURE" width="768" height="768" fetchpriority="high"><div class="hud-panel hud-a"><strong>MÉTODO</strong><span>Objetivo · evidencia · revisión</span></div><div class="hud-panel hud-b"><strong>CRITERIO</strong><span>Fuentes antes que respuestas</span></div></div></section><section class="section compact"><div class="section-head reveal"><span>Empieza por una tarea</span><h2>La herramienta viene después del problema</h2><p>Elige una ruta y aplica un proceso que puedas explicar y repetir.</p></div><div class="guide-list"><a href="guias/como-hacer-prompts-para-tareas-universitarias.html"><span class="editorial-kicker">Método</span><h3>Escribir mejores instrucciones</h3><p>Convierte una petición vaga en una tarea con contexto, formato y verificación.</p></a><a href="guias/como-usar-ia-sin-plagio.html"><span class="editorial-kicker">Integridad</span><h3>Usar IA sin perder autoría</h3><p>Semáforo de riesgos, declaración de uso, fuentes y privacidad.</p></a><a href="guias/mejores-ia-para-estudiar-y-resumir.html"><span class="editorial-kicker">Estudio</span><h3>Estudiar y resumir textos</h3><p>Un flujo en cuatro pasadas que termina con práctica de recuperación.</p></a><a href="guias/mejores-ia-para-presentaciones.html"><span class="editorial-kicker">Presentaciones</span><h3>Construir una presentación defendible</h3><p>Separa argumento, diseño y ensayo para evitar diapositivas vacías.</p></a></div></section><section class="section compact"><div class="section-head reveal"><span>Cómo trabajamos</span><h2>Contenido diseñado para ser comprobado</h2></div><div class="method-grid"><article class="method-step"><span>01</span><h3>Delimitamos la tarea</h3><p>No publicamos una lista de funciones sin explicar qué problema resuelve.</p></article><article class="method-step"><span>02</span><h3>Usamos fuentes primarias</h3><p>Las funciones se contrastan con documentación del proveedor.</p></article><article class="method-step"><span>03</span><h3>Mostramos límites</h3><p>Cada guía incluye riesgos, verificación y condiciones que pueden cambiar.</p></article></div><p class="quality-note">La IA puede apoyar la investigación y la estructura de un borrador. La selección, edición y publicación final pasan por revisión humana. <a class="text-link-strong" href="metodologia.html">Consulta el proceso editorial completo</a>.</p></section><section class="section compact"><div class="section-head reveal"><span>Comparar con criterio</span><h2>Decisiones basadas en tareas</h2><p>Las comparativas usan la misma consigna, los mismos criterios y fuentes oficiales.</p></div><div class="guide-list"><a href="comparativas/chatgpt-vs-gemini.html"><h3>ChatGPT vs Gemini</h3><p>Flujo conversacional, servicios conectados y verificación.</p></a><a href="comparativas/perplexity-vs-chatgpt.html"><h3>Perplexity vs ChatGPT</h3><p>Descubrir fuentes frente a comprender y estructurar.</p></a></div></section></main>${footer("")}`;
}

function aboutPage() {
  const canonical=`${base}/sobre.html`; const description="Quién edita IA FUTURE, por qué existe el proyecto y cómo se revisa el contenido sobre inteligencia artificial.";
  return `${head({title:"Sobre IA FUTURE y su criterio editorial",description,canonical,type:"website",schema:[{"@context":"https://schema.org","@type":"AboutPage",name:"Sobre IA FUTURE",url:canonical}]})}${header("","sobre")}<main id="top"><section class="page-hero image-hero"><img src="assets/img/ai-learning-visual.webp" alt="Mesa editorial de IA FUTURE para analizar herramientas de inteligencia artificial" width="1280" height="768"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Sobre el proyecto</span><h1>IA FUTURE explica la IA desde la tarea, no desde la moda</h1><p>El sitio ayuda a estudiantes y creadores a elegir herramientas, formular mejores instrucciones y verificar resultados.</p></div></section><section class="section compact"><article class="article-prose"><section><h2>Quién publica</h2><p>IA FUTURE es un proyecto editorial independiente. Los artículos se firman como <strong>Equipo editorial IA FUTURE</strong> porque representan una revisión común del sitio y no una opinión anónima atribuida a una herramienta.</p><p>El contacto editorial está disponible públicamente y las correcciones se incorporan cuando una función cambia o una fuente primaria contradice el contenido publicado.</p></section><section><h2>Por qué existe</h2><p>Muchas guías de inteligencia artificial enumeran funciones sin explicar cómo comprobar un resultado. IA FUTURE se centra en la parte que el usuario debe conservar: definir el objetivo, proteger los datos, contrastar fuentes y decidir qué versión final puede defender.</p></section><section><h2>Cómo se crea el contenido</h2><p>La investigación comienza con documentación oficial y una tarea reproducible. La IA puede utilizarse para organizar notas o detectar preguntas pendientes, pero no sustituye la selección de fuentes, la edición ni la comprobación final. Cuando una función depende de región, cuenta o plan, evitamos presentarla como universal.</p></section><section><h2>Independencia y monetización</h2><p>IA FUTURE no está afiliado a las herramientas que compara salvo indicación expresa. Los enlaces a productos se incluyen como fuentes o accesos oficiales. El sitio puede financiarse mediante publicidad y productos digitales; esa monetización no modifica los criterios de selección ni garantiza una valoración positiva.</p></section><section><h2>Correcciones</h2><p>Para señalar un error, incluye la URL, el fragmento y una fuente verificable en la página de <a class="text-link-strong" href="contacto.html">contacto</a>. Las páginas muestran una fecha de revisión para distinguir contenido editorial vigente de material archivado.</p></section></article></section></main>${footer("")}`;
}

function methodologyPage() {
  const canonical=`${base}/metodologia.html`; const description="Metodología editorial de IA FUTURE para seleccionar fuentes, comparar herramientas y revisar contenido asistido por inteligencia artificial.";
  return `${head({title:"Metodología editorial | IA FUTURE",description,canonical,type:"website",schema:[{"@context":"https://schema.org","@type":"WebPage",name:"Metodología editorial de IA FUTURE",url:canonical}]})}${header("","sobre")}<main id="top"><section class="page-hero slim"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Transparencia</span><h1>Cómo investigamos, comparamos y corregimos</h1><p>Una guía solo se publica cuando explica la tarea, permite verificar el resultado y distingue hechos de recomendaciones.</p></div></section><section class="section compact"><div class="section-head reveal"><span>Proceso editorial</span><h2>Seis pasos antes de publicar</h2><p>Cada etapa deja una decisión o una comprobación visible para el lector.</p></div><div class="method-grid"><article class="method-step"><span>01</span><h3>Pregunta concreta</h3><p>Definimos usuario, tarea y resultado esperado.</p></article><article class="method-step"><span>02</span><h3>Fuentes primarias</h3><p>Revisamos documentación y centros de ayuda oficiales.</p></article><article class="method-step"><span>03</span><h3>Prueba reproducible</h3><p>Usamos la misma consigna y criterios al comparar.</p></article><article class="method-step"><span>04</span><h3>Límites</h3><p>Señalamos incertidumbre, privacidad y dependencia de planes.</p></article><article class="method-step"><span>05</span><h3>Edición humana</h3><p>La versión final se revisa por claridad, exactitud y utilidad.</p></article><article class="method-step"><span>06</span><h3>Actualización</h3><p>Mostramos fecha y retiramos páginas que ya no aportan.</p></article></div></section><section class="section compact"><article class="article-prose"><section><h2>Matriz de evaluación</h2><table class="decision-table"><thead><tr><th>Criterio</th><th>Pregunta</th></tr></thead><tbody><tr><td>Utilidad</td><td>¿El lector puede completar una tarea concreta?</td></tr><tr><td>Trazabilidad</td><td>¿Puede abrir las fuentes y comprobar afirmaciones?</td></tr><tr><td>Originalidad</td><td>¿La página aporta método, prueba o análisis y no solo un resumen?</td></tr><tr><td>Control</td><td>¿El usuario conserva decisiones, datos y versión final?</td></tr><tr><td>Vigencia</td><td>¿Se evitan límites o precios que cambian sin aviso?</td></tr></tbody></table></section><section><h2>Uso de automatización</h2><p>Herramientas de IA pueden apoyar la lluvia de ideas, la estructura o la detección de repeticiones. No publicamos automáticamente sus respuestas. Las afirmaciones sobre productos deben enlazar documentación primaria y toda guía pasa por edición humana.</p></section><section><h2>Qué no publicamos</h2><ul><li>Páginas creadas solo para variaciones de una palabra clave.</li><li>Listas sin criterio de selección.</li><li>Comparativas sin una tarea común.</li><li>Precios o límites no comprobados.</li><li>Referencias generadas que no se puedan abrir.</li></ul></section>${sources([["Contenido útil y centrado en personas, Google", "https://developers.google.com/search/docs/fundamentals/creating-helpful-content"],["Guía sobre contenido con IA generativa, Google", "https://developers.google.com/search/docs/fundamentals/using-gen-ai-content"]])}</article></section></main>${footer("")}`;
}

function hubPage() {
  const canonical=`${base}/noticias.html`; const description="Biblioteca editorial de IA FUTURE con guías prácticas y comparativas verificables para estudiar y crear con inteligencia artificial.";
  const items=[...guides,...comparisons];
  return `${head({title:"Guías y comparativas de IA | IA FUTURE",description,canonical,type:"website",schema:[{"@context":"https://schema.org","@type":"CollectionPage",name:"Biblioteca editorial IA FUTURE",url:canonical}]})}${header("","guias")}<main id="top"><section class="page-hero image-hero visual-hero"><img src="assets/img/ai-tools-atlas.webp" alt="Atlas editorial de herramientas y métodos de inteligencia artificial" width="1280" height="768"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Biblioteca editorial</span><h1>Guías que terminan en una decisión comprobable</h1><p>Cada artículo parte de una tarea concreta, muestra un proceso y enlaza sus fuentes primarias.</p></div></section><section class="section compact"><div class="section-head reveal"><span>Contenido revisado</span><h2>Elige una tarea o una comparación</h2><p>Ocho rutas con un método explícito, límites y fuentes para comprobar.</p></div><div class="guide-list">${items.map(item=>`<a href="${item.file}"><span class="editorial-kicker">${item.category}</span><h3>${item.title}</h3><p>${item.description}</p></a>`).join("")}</div></section><section class="section compact"><p class="quality-note">Las páginas antiguas basadas en variaciones de palabras clave se retiraron del índice. Consulta <a class="text-link-strong" href="metodologia.html">la metodología editorial</a> para conocer los criterios de inclusión.</p></section></main>${footer("")}`;
}

function iaPrimer() {
  const canonical=`${base}/ia.html`; const description="Introducción práctica a la inteligencia artificial generativa: capacidades, límites, verificación, privacidad y criterios de uso.";
  return `${head({title:"Qué es la IA generativa y cómo evaluarla | IA FUTURE",description,canonical,schema:[articleSchema({title:"Qué es la IA generativa y cómo evaluarla",description,canonical})]})}${header("","catalogo")}<main id="top"><section class="page-hero image-hero"><img src="assets/img/ai-comparison-dashboard.webp" alt="Panel para evaluar respuestas de inteligencia artificial" width="1280" height="768"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Fundamentos</span><h1>Entender la IA antes de delegarle una tarea</h1><p>Los modelos generativos producen respuestas plausibles a partir de patrones. No son una base de datos infalible ni sustituyen una fuente primaria.</p>${editorialMeta("")}</div></section><section class="section compact"><article class="article-prose"><section><h2>Qué hace un modelo generativo</h2><p>Recibe una instrucción y produce texto, imagen, código u otro contenido según patrones aprendidos y contexto disponible. Puede resumir, explicar, transformar formatos y proponer alternativas. Esa fluidez no garantiza exactitud.</p></section><section><h2>Cuatro riesgos que debes separar</h2><ul><li><strong>Error factual:</strong> una afirmación incorrecta presentada con seguridad.</li><li><strong>Fuente inexistente:</strong> una referencia plausible que no puede abrirse.</li><li><strong>Fuga de datos:</strong> compartir información sin permiso.</li><li><strong>Pérdida de autoría:</strong> aceptar una versión que ya no puedes explicar.</li></ul></section><section><h2>Una prueba sencilla para cualquier herramienta</h2><ol><li>Elige una tarea cuya respuesta correcta conozcas.</li><li>Define criterios antes de preguntar.</li><li>Guarda la primera respuesta.</li><li>Introduce un dato contradictorio.</li><li>Comprueba si detecta el problema.</li><li>Verifica fuera de la herramienta.</li></ol></section><section><h2>Cómo elegir</h2><table class="decision-table"><thead><tr><th>Necesidad</th><th>Busca</th></tr></thead><tbody><tr><td>Aprender</td><td>Explicaciones graduales y retroalimentación.</td></tr><tr><td>Investigar</td><td>Enlaces trazables y filtros de fecha.</td></tr><tr><td>Crear</td><td>Control de edición y derechos claros.</td></tr><tr><td>Automatizar</td><td>Permisos limitados, registro y reversibilidad.</td></tr></tbody></table></section>${sources([["Introducción a la IA generativa, Google", "https://support.google.com/gemini/answer/13594961"],["Contenido útil, Google Search Central", "https://developers.google.com/search/docs/fundamentals/creating-helpful-content"]])}</article></section></main>${footer("")}`;
}

function promptsPage() {
  const canonical=`${base}/prompts.html`; const description="Biblioteca de prompts verificables para estudiar, investigar, programar, escribir y preparar presentaciones con IA.";
  const blocks=[
    ["Tutor socrático","Hazme una pregunta a la vez sobre [tema]. Espera mi respuesta, corrige con una explicación breve y aumenta la dificultad. No muestres la solución antes de que responda."],
    ["Lectura crítica","Analiza únicamente el texto adjunto. Separa tesis, evidencia, supuestos y preguntas abiertas. Marca cualquier inferencia que no aparezca de forma explícita."],
    ["Investigación","Ayúdame a delimitar [tema] en una pregunta investigable. Propón términos de búsqueda, tipos de fuentes primarias y criterios para descartar material débil. No inventes referencias."],
    ["Programación","Explica el error antes de proponer cambios. Crea una prueba que lo reproduzca, ofrece la modificación mínima y explica qué caso límite sigue abierto."],
    ["Presentación","Convierte mi esquema en [número] diapositivas. Una idea por pantalla, evidencia por verificar, sugerencia visual con función y nota del expositor."],
    ["Revisión de borrador","No reescribas todavía. Evalúa tesis, estructura, evidencia, claridad y voz. Haz preguntas concretas y señala dónde falta una fuente."]
  ];
  return `${head({title:"Prompts verificables para estudiar y crear | IA FUTURE",description,canonical,schema:[articleSchema({title:"Prompts verificables para estudiar y crear",description,canonical})]})}${header("","prompts")}<main id="top"><section class="page-hero image-hero"><img src="assets/img/prompt-ebooks-showcase.webp" alt="Cuaderno visual con prompts organizados por objetivo y verificación" width="1280" height="768"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Biblioteca práctica</span><h1>Prompts que incluyen una forma de comprobar la respuesta</h1><p>Copia una estructura, sustituye el contexto y conserva siempre el paso de revisión humana.</p>${editorialMeta("")}</div></section><section class="section compact"><article class="article-prose"><section><h2>Antes de copiar</h2><p>Un prompt útil describe la tarea y el criterio de éxito. No pegues datos personales ni esperes que una frase funcione igual en todas las herramientas.</p></section>${blocks.map(([name,prompt],i)=>`<section><h2>${i+1}. ${name}</h2><div class="prompt-sample">${prompt}</div><button class="copy-mini" type="button" data-copy="${prompt.replaceAll('"','&quot;')}">Copiar prompt</button></section>`).join("")}<section><h2>Cómo adaptar cualquiera de estos prompts</h2><ul><li>Añade la materia, audiencia y nivel.</li><li>Incluye solo material permitido.</li><li>Define el formato de salida.</li><li>Pide supuestos, dudas y fuentes por verificar.</li><li>Evalúa el resultado con una rúbrica propia.</li></ul></section>${sources([["Guía de prompting de Anthropic", "https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering/overview"],["Consejos para usar Perplexity", "https://www.perplexity.ai/help-center/en/articles/10352971-practical-tips-for-using-perplexity"]])}</article></section></main>${footer("")}`;
}

function resourcesPage() {
  const canonical=`${base}/recursos.html`; const description="Recursos de verificación, privacidad, citación y evaluación para usar inteligencia artificial con responsabilidad.";
  return `${head({title:"Recursos para verificar contenido de IA | IA FUTURE",description,canonical,schema:[articleSchema({title:"Recursos para verificar contenido de IA",description,canonical})]})}${header("","recursos")}<main id="top"><section class="page-hero image-hero"><img src="assets/img/ai-learning-visual.webp" alt="Proceso de verificación humana de contenido producido con inteligencia artificial" width="1280" height="768"><div class="page-hero-copy reveal"><span class="eyebrow"><span></span> Recursos</span><h1>Comprobar es parte del trabajo</h1><p>Listas prácticas para fuentes, privacidad, derechos, decisiones de pago y entrega académica.</p>${editorialMeta("")}</div></section><section class="section compact"><article class="article-prose"><section><h2>Verificación de datos</h2><ul><li>Identifica qué afirmaciones pueden comprobarse.</li><li>Busca documentos primarios y fechas.</li><li>Abre la fuente completa, no solo el fragmento.</li><li>Confirma que la evidencia respalda la conclusión.</li><li>Registra qué cambiaste después de verificar.</li></ul></section><section><h2>Privacidad</h2><p>Elimina nombres, correos, números, ubicaciones y cualquier combinación que identifique a una persona. No subas información institucional, médica o contractual sin permiso.</p></section><section><h2>Gratis frente a pago</h2><p>No pagues por una lista de funciones. Prueba una tarea repetida durante una semana y mide tiempo ahorrado, calidad, límites y facilidad de verificación. Revisa renovación y tratamiento de datos antes de contratar.</p></section><section><h2>Derechos y contenido visual</h2><p>Consulta los términos de la herramienta y la licencia de cada recurso. Evita logos, personajes o estilos que puedan crear confusión. Una imagen generada sigue necesitando revisión de texto, manos, rostros y contexto.</p></section><section><h2>Entrega académica</h2><ul><li>Responde a la consigna, no al prompt.</li><li>Conserva tu voz y tus notas.</li><li>Declara la ayuda cuando corresponda.</li><li>Verifica todas las citas.</li><li>Entrega solo contenido que puedas defender.</li></ul></section>${sources([["Guía de contenido con IA generativa, Google", "https://developers.google.com/search/docs/fundamentals/using-gen-ai-content"],["Contenido útil y confiable, Google", "https://developers.google.com/search/docs/fundamentals/creating-helpful-content"]])}</article></section></main>${footer("")}`;
}

function noindex(file, canonical) {
  let html=read(file);
  if (html.includes('name="robots"')) html=html.replace(/<meta name="robots" content="[^"]*">/, '<meta name="robots" content="noindex,follow">');
  else html=html.replace('<meta name="viewport" content="width=device-width, initial-scale=1">','<meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="robots" content="noindex,follow">');
  html=html.replace(/\s*<meta name="google-adsense-account"[^>]*>/g,"").replace(/\s*<!-- Google AdSense -->\s*/g,"\n").replace(/\s*<script async src="https:\/\/pagead2\.googlesyndication\.com\/pagead\/js\/adsbygoogle\.js\?client=ca-pub-7507181626477156"\s*crossorigin="anonymous"><\/script>/g,"");
  html=html.replace(/<link rel="canonical" href="[^"]+">/,`<link rel="canonical" href="${canonical}">`);
  write(file,html);
}

function cleanCatalog() {
  let html=read("catalogo.html");
  const keep=new Set(tools.map(tool=>tool.slug));
  for (const match of html.matchAll(/href="ias\/([a-z0-9-]+)\.html">Abrir guia extensa<\/a>/g)) {
    if (!keep.has(match[1])) html=html.replace(match[0],"");
  }
  html=html.replace(/Guia universitaria de inteligencia artificial/g,"IA práctica con criterio editorial").replace(/Abre cada guia para aprender desde cero\./g,"Abre las fichas revisadas o consulta el sitio oficial de cada herramienta.");
  if (!html.includes("Explora 17 herramientas con criterios claros")) html=html.replace('<section class="section"><div class="filter-panel reveal">','<section class="section"><div class="section-head reveal"><span>Selección por tarea</span><h2>Explora 17 herramientas con criterios claros</h2><p>Filtra el catálogo y abre las fichas que ya pasaron revisión editorial.</p></div><div class="filter-panel reveal">');
  if (!html.includes("assets/css/editorial.css")) html=html.replace('<link rel="stylesheet" href="assets/css/seo.css">','<link rel="stylesheet" href="assets/css/seo.css">\n  <link rel="stylesheet" href="assets/css/editorial.css">');
  write("catalogo.html",html);
}

function normalizeGlobalCopy() {
  const files=[];
  const walk=dir=>{for(const entry of fs.readdirSync(dir,{withFileTypes:true})){const full=path.join(dir,entry.name);if(entry.isDirectory())walk(full);else if(entry.name.endsWith(".html"))files.push(path.relative(root,full).replaceAll("\\","/"));}};
  walk(root);
  for(const file of files){let html=read(file);html=html.replaceAll("Directorio educativo y prototipo academico sobre herramientas de inteligencia artificial.","Guías independientes para aprender y usar inteligencia artificial con verificación humana.").replaceAll("Guia universitaria de inteligencia artificial","IA práctica con criterio editorial").replaceAll("SEO y aprendizaje","Biblioteca editorial").replaceAll("Paginas creadas para atraer visitas desde Google.","Guías creadas para resolver tareas concretas.").replaceAll("Respuestas directas para usuarios que llegan desde Google.","Respuestas breves para dudas frecuentes.");write(file,html);}
}

function sitemap() {
  const curated=["","ia.html","catalogo.html","prompts.html","noticias.html","recursos.html","sobre.html","metodologia.html","contacto.html","privacidad.html","terminos.html",...guides.map(x=>x.file),...comparisons.map(x=>x.file),...tools.map(x=>`ias/${x.slug}.html`)];
  const rows=curated.map((file,index)=>`  <url><loc>${base}/${file}</loc><lastmod>${reviewed}</lastmod><changefreq>${index===0?"weekly":"monthly"}</changefreq><priority>${index===0?"1.0":index<7?"0.8":"0.7"}</priority></url>`).join("\n");
  write("sitemap.xml",`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${rows}\n</urlset>\n`);
}

write("index.html",homepage());
write("sobre.html",aboutPage());
write("metodologia.html",methodologyPage());
write("noticias.html",hubPage());
write("ia.html",iaPrimer());
write("prompts.html",promptsPage());
write("recursos.html",resourcesPage());
for(const guide of guides) write(guide.file,articlePage(guide));
for(const comparison of comparisons) write(comparison.file,articlePage(comparison));
for(const tool of tools) write(`ias/${tool.slug}.html`,toolPage(tool));
cleanCatalog();

const excluded={
  "404.html":`${base}/404.html`,
  "herramientas-ia.html":`${base}/catalogo.html`,
  "inteligencia-artificial.html":`${base}/ia.html`,
  "prompts-ia.html":`${base}/prompts.html`,
  "ia-future.html":`${base}/`,
  "ebooks.html":`${base}/ebooks.html`,
  "guias/mejores-ias-gratis-estudiantes-2026.html":`${base}/noticias.html`,
  "guias/ia-para-crear-imagenes-gratis.html":`${base}/noticias.html`,
  "guias/prompts-para-marketing-con-ia.html":`${base}/noticias.html`,
  "guias/como-vender-ebooks-con-ia.html":`${base}/noticias.html`
};
for(const [file,canonical] of Object.entries(excluded)) noindex(file,canonical);
for(const file of fs.readdirSync(path.join(root,"ias")).filter(name=>name.endsWith(".html"))){const slug=file.replace(/\.html$/,"");if(!tools.some(tool=>tool.slug===slug))noindex(`ias/${file}`,`${base}/catalogo.html`);}
normalizeGlobalCopy();
sitemap();
console.log(`Editorial rebuild complete: ${guides.length} guides, ${comparisons.length} comparisons, ${tools.length} curated tool pages.`);
